 * @param position       检查点顺序，从1连续递增
 * @param createdAt      配置时间，Unix毫秒时间戳
 */
public record CheckpointRow(
        String raceId,
        String checkpointCode,
        int position,
        long createdAt
) implements CheckpointView {
}

