public ServiceResult assignGroups(String raceId, AssignGroupsRequest request) {
    // canonical params: groups sorted by groupCode, bibs sorted
    List<AssignGroupsRequest.GroupDefinition> definitions = request.groups().stream()
            .sorted(Comparator.comparing(AssignGroupsRequest.GroupDefinition::groupCode))
            .toList();
    return withIdempotency(request.requestId(), "ASSIGN_GROUPS",
            orderedParams(
                    "raceId", raceId,
                    "expectedVersion", request.expectedVersion(),
                    "groups", definitions.stream()
                            .map(def -> def.groupCode() + ":" + def.bibs().stream().sorted().toList())
                            .toList()),
            () -> {
                RaceRow race = requireOpenRace(raceId, request.expectedVersion());
                validateGroupDefinitions(request.groups());
                if (!repository.findGroups(raceId).isEmpty()) {
                    throw new ConflictException("赛事已划分分组，划分后不可修改: " + raceId);
                }
                // validate runners exist
                for (def : request.groups()) for (bib : def.bibs()) requireRunner(raceId, bib);
                bumpVersion(race, request.expectedVersion());
                long now = clock.millis();
                repository.insertGroups(...);
                repository.insertGroupMembers(...);
                return ServiceResult.created(buildGroupsResponse(raceId, request.expectedVersion() + 1));
            });
}
```

