```java
@Override
@Transactional
public ServiceResult generateAdvancement(String raceId, GenerateAdvancementRequest request) {
    return withIdempotency(request.requestId(), "GENERATE_ADVANCEMENT",
            orderedParams(
                    "raceId", raceId,
                    "advancementKey", request.advancementKey(),
                    "quotaPerGroup", request.quotaPerGroup(),
                    "wildcardCount", request.wildcardCount(),
                    "expectedVersion", request.expectedVersion()),
            () -> {
                RaceRow race = requireOpenRace(raceId, request.expectedVersion());
                int quota = request.quotaPerGroup();
                int wildcard = request.wildcardCount();
                if (quota < 1 || quota > 8) throw new BadRequestException("每组直接晋级名额Q必须在 1~8 之间");
                if (wildcard < 0 || wildcard > 8) throw new BadRequestException("补位名额W必须在 0~8 之间");
                List<GroupRow> groups = repository.findGroups(raceId);
                if (groups.isEmpty()) {
                    throw new ConflictException("赛事尚未划分分组，无法生成晋级名单: " + raceId);
                }
                if (repository.findActiveAdvancement(raceId).isPresent()) {
                    throw new ConflictException("赛事已存在生效晋级名单，请先撤销: " + raceId);
                }
                if (repository.findAdvancement(request.advancementKey()).isPresent()) {
                    throw new ConflictException("advancementKey 已存在: " + request.advancementKey());
                }
                List<GroupMemberRow> members = repository.findGroupMembers(raceId);
                // compute current results
                List<ResultEntry> entries = ResultCalculator.compute(
                        repository.findRunners(raceId), repository.findPenalties(raceId),
                        repository.findCheckpoints(raceId), repository.findAllTimings(raceId));
                Map<String, ResultEntry> rankedByBib = new HashMap<>();
                for (ResultEntry entry : entries) {
                    if (entry.status() == EntryStatus.RANKED) {
                        rankedByBib.put(entry.bib(), entry);
                    }
                }
                Map<String, Long> totalTimeByBib = ...;
                List<GroupInput> groupInputs = groups.stream().map(g -> new GroupInput(g.groupCode(),
                        members.stream().filter(m -> m.groupCode().equals(g.groupCode())).map(GroupMemberRow::bib).toList())).toList();
                AdvancementOutcome outcome = AdvancementCalculator.compute(groupInputs, totalTimeByBib, quota, wildcard);
                if (outcome instanceof Insufficient ins) {
                    throw new UnprocessableEntityException("分组 " + ins.groupCode() + " 有效选手不足: 需要" + ins.required() + "名, 实际" + ins.actual() + "名");
                }
                Plan plan = (Plan) outcome;
                int newVersion = request.expectedVersion() + 1;
                bumpVersion(race, request.expectedVersion());
                long now = clock.millis();
                List<AdvancementEntryRow> entryRows = new ArrayList<>();
                int order = 0;
                for (AdvanceEntry e : plan.entries()) {
                    ResultEntry re = rankedByBib.get(e.bib());
                    entryRows.add(new AdvancementEntryRow(request.advancementKey(), e.bib(), e.groupCode(),
                            e.type().name(), e.rank(), re.finishTimeMs(), re.penaltyMs(), re.totalTimeMs(), order++));
                }
                AdvancementRow row = new AdvancementRow(request.advancementKey(), raceId, newVersion, quota, wildcard,
                        plan.expectedCount(), plan.actualCount(), plan.overflowReason(), "ACTIVE", now, null, entryRows);
                try {
                    repository.insertAdvancement(row);
                } catch (DuplicateKeyException ex) {
                    throw new ConflictException("advancementKey 已存在: " + request.advancementKey());
                }
                repository.insertActiveAdvancement(raceId, request.advancementKey());
                return ServiceResult.created(toAdvancementResponse(row));
            });
}
```

Note: entries from AdvancementCalculator are ordered: DIRECT per group (in group iteration order — groups sorted by groupCode since findGroups orders by group_code), then WILDCARD by pool rank. Good display order.

Wait — one subtlety: `re.finishTimeMs()` returns Long, AdvancementEntryRow takes long — auto-unbox, RANKED entries have non-null. OK.

