private static void validateGroupDefinitions(List<GroupDefinition> definitions) {
    if (definitions.size() < 2 || definitions.size() > 8) {
        throw new BadRequestException("分组数量必须在 2~8 之间");
    }
    Set<String> groupCodes = new HashSet<>();
    Set<String> allBibs = new HashSet<>();
    for (GroupDefinition def : definitions) {
        if (def.groupCode() == null || def.groupCode().isBlank()) throw new BadRequestException("分组代码不能为空");
        if (!groupCodes.add(def.groupCode())) throw new BadRequestException("分组代码重复: " + def.groupCode());
        if (def.bibs().size() < 2 || def.bibs().size() > 16) throw new BadRequestException("每组选手数量必须在 2~16 之间: " + def.groupCode());
        for (String bib : def.bibs()) {
            if (bib == null || bib.isBlank()) throw new BadRequestException("参赛号不能为空");
            if (!allBibs.add(bib)) throw new BadRequestException("同一选手只能属于一个分组: " + bib);
        }
    }
}
```

